arguments.new_str:
namespace Payments;

public interface IPaymentProcessor
{
    Task<string> SubmitChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<string> SubmitRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProcessor _processor;
    private readonly decimal _maxChargeAmount;

    public PaymentGateway(IPaymentProcessor processor, decimal maxChargeAmount = 10_000m)
    {
        _processor = processor ?? throw new ArgumentNullException(nameof(processor));
        _maxChargeAmount = maxChargeAmount;
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount must be positive.");

        if (amount > _maxChargeAmount)
            return new ChargeResult(ChargeId: string.Empty, Success: false, ErrorMessage: $"Amount exceeds maximum of {_maxChargeAmount:C}.");

        try
        {
            var chargeId = await _processor.SubmitChargeAsync(cardToken, amount, cancellationToken);
            return new ChargeResult(chargeId, Success: true, ErrorMessage: null);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return new ChargeResult(ChargeId: string.Empty, Success: false, ErrorMessage: ex.Message);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        try
        {
            var refundId = await _processor.SubmitRefundAsync(chargeId, cancellationToken);
            return new RefundResult(refundId, Success: true, ErrorMessage: null);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return new RefundResult(RefundId: string.Empty, Success: false, ErrorMessage: ex.Message);
        }
    }

    public static WebhookEvent ParseWebhook(string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        if (payload.Contains("charge.completed"))
            return new WebhookEvent("charge.completed", payload);
        if (payload.Contains("refund.completed"))
            return new WebhookEvent("refund.completed", payload);

        throw new InvalidOperationException($"Unknown webhook event in payload.");
    }
}

public record ChargeResult(string ChargeId, bool Success, string? ErrorMessage);
public record RefundResult(string RefundId, bool Success, string? ErrorMessage);
public record WebhookEvent(string EventType, string RawPayload);

