using Payments;

namespace PaymentGateway.Tests;

/// <summary>
/// Fake processor that returns predictable results for unit testing.
/// </summary>
internal sealed class FakePaymentProcessor : IPaymentProcessor
{
    public string NextChargeId { get; set; } = "ch_abc123";
    public string NextRefundId { get; set; } = "rf_xyz789";
    public Exception? ChargeException { get; set; }
    public Exception? RefundException { get; set; }

    public decimal? LastChargedAmount { get; private set; }
    public string? LastChargedToken { get; private set; }
    public string? LastRefundedChargeId { get; private set; }

    public Task<string> SubmitChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        LastChargedToken = cardToken;
        LastChargedAmount = amount;

        return ChargeException is not null
            ? Task.FromException<string>(ChargeException)
            : Task.FromResult(NextChargeId);
    }

    public Task<string> SubmitRefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        LastRefundedChargeId = chargeId;

        return RefundException is not null
            ? Task.FromException<string>(RefundException)
            : Task.FromResult(NextRefundId);
    }
}

using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly FakePaymentProcessor _processor = new();
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _gateway = new Payments.PaymentGateway(_processor);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ReturnsSuccessWithChargeId()
    {
        _processor.NextChargeId = "ch_test_001";

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_test_001", result.ChargeId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ForwardsTokenAndAmountToProcessor()
    {
        await _gateway.ChargeAsync("tok_mastercard", 75.00m);

        Assert.AreEqual("tok_mastercard", _processor.LastChargedToken);
        Assert.AreEqual(75.00m, _processor.LastChargedAmount);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
