using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly FakePaymentProcessor _processor = new();
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _gateway = new Payments.PaymentGateway(_processor);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        _processor.NextRefundId = "rf_test_001";

        var result = await _gateway.RefundAsync("ch_abc123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("rf_test_001", result.RefundId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeIdToProcessor()
    {
        await _gateway.RefundAsync("ch_original_charge");

        Assert.AreEqual("ch_original_charge", _processor.LastRefundedChargeId);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorThrows_ReturnsFailureWithMessage()
    {
        _processor.RefundException = new InvalidOperationException("Refund not allowed");

        var result = await _gateway.RefundAsync("ch_abc123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
        Assert.AreEqual("Refund not allowed", result.ErrorMessage);
    }

    [TestMethod]
    public async Task RefundAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync("ch_abc123", cts.Token));
    }
}

