using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayWebhookTests
{
    [TestMethod]
    public void ParseWebhook_ChargeCompleted_ReturnsCorrectEventType()
    {
        var result = Payments.PaymentGateway.ParseWebhook("{\"type\":\"charge.completed\",\"id\":\"ch_1\"}");

        Assert.AreEqual("charge.completed", result.EventType);
        Assert.Contains("charge.completed", result.RawPayload);
    }

    [TestMethod]
    public void ParseWebhook_RefundCompleted_ReturnsCorrectEventType()
    {
        var result = Payments.PaymentGateway.ParseWebhook("{\"type\":\"refund.completed\",\"id\":\"rf_1\"}");

        Assert.AreEqual("refund.completed", result.EventType);
    }

    [TestMethod]
    public void ParseWebhook_UnknownEvent_ThrowsInvalidOperation()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => Payments.PaymentGateway.ParseWebhook("{\"type\":\"unknown.event\"}"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ParseWebhook_InvalidPayload_ThrowsArgumentException(string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => Payments.PaymentGateway.ParseWebhook(payload!));
    }

    [TestMethod]
    public void ParseWebhook_PreservesRawPayload()
    {
        const string payload = "{\"type\":\"charge.completed\",\"data\":{\"amount\":100}}";

        var result = Payments.PaymentGateway.ParseWebhook(payload);

        Assert.AreEqual(payload, result.RawPayload);
    }
}

